import React, { useState } from 'react';

const aboutDetails = [
	{
		emoji: '😌',
		title: 'Changes day to day',
		details: 'Mental health can fluctuate daily due to stress, sleep, relationships, and more. It’s normal for your mood and feelings to change from day to day.',
	},
	{
		emoji: '💬',
		title: 'Feeling sad is normal',
		details: 'Everyone feels sad, anxious, or down sometimes. These feelings are a natural part of life and don’t mean something is wrong with you.',
	},
	{
		emoji: '🤝',
		title: 'You’re not alone',
		details: 'Many teens experience mental health challenges. Reaching out for support is common and you are never alone in how you feel.',
	},
	{
		emoji: '🧠',
		title: 'Mind care matters',
		details: 'Taking care of your mind is just as important as caring for your body. Good mental health helps you enjoy life and cope with stress.',
	},
	{
		emoji: '🌈',
		title: 'Support helps',
		details: 'Talking to someone you trust or a professional can make a big difference. Support can help you feel better and find solutions.',
	},
	{
		emoji: '🕊️',
		title: 'It’s okay to take a break',
		details: 'Rest and self-care are important for your mental health. Taking breaks can help you recharge and manage stress.',
	},
];

const AboutSection = () => {
	const [openIndex, setOpenIndex] = useState(null);
	return (
		<section id="about" className="card-area">
			<h2>About Mental Health</h2>
			<p
				style={{
					fontSize: '1.13rem',
					color: '#2d7fa5',
					fontWeight: 500,
					marginBottom: 18,
				}}
			>
				🌱 Everyone has mental health! It’s about how we think, feel, and cope
				with life’s ups and downs.
			</p>
			<ul className="about-bullets about-bullets-fancy" role="list">
				{aboutDetails.map((item, idx) => (
					<li
						key={item.title}
						tabIndex="0"
						className={openIndex === idx ? 'open' : ''}
						onClick={e => {
							// Prevent button click from bubbling and toggling twice
							if (e.target.closest('.about-dropdown-btn')) return;
							setOpenIndex(openIndex === idx ? null : idx);
						}}
						onKeyDown={e => {
							if (e.key === 'Enter' || e.key === ' ') {
								e.preventDefault();
								setOpenIndex(openIndex === idx ? null : idx);
							}
						}}
						aria-expanded={openIndex === idx}
						aria-controls={`about-detail-${idx}`}
						role="button"
					>
						<div className="about-bullet-row">
							<span className="about-emoji">{item.emoji}</span>
							<span className="about-bullet-text">{item.title}</span>
							<button
								aria-expanded={openIndex === idx}
								aria-controls={`about-detail-${idx}`}
								className="about-dropdown-btn"
								style={{ marginLeft: 12 }}
								onClick={e => {
									e.stopPropagation();
									setOpenIndex(openIndex === idx ? null : idx);
								}}
							>
								{openIndex === idx ? '▲' : '▼'}
								<span className="sr-only">Show more about {item.title}</span>
							</button>
						</div>
						{openIndex === idx && (
							<div
								id={`about-detail-${idx}`}
								className="about-dropdown-detail"
								style={{
									textAlign: 'center',
									marginLeft: '6%', // visually center but slightly left
									maxWidth: '88%',
								}}
							>
								{item.details}
							</div>
						)}
					</li>
				))}
			</ul>
			<div className="about-remember-box">
				<strong>Remember:</strong> <br />
				<span className="about-remember-text">Asking for help is strong.</span>
			</div>

			<div className="about-subsections">
				<div className="about-subsection teen-info">
					<h3>Understanding Teen Mental Health</h3>
					<p className="subsection-intro">
						Mental health affects every aspect of a teenager's life - from school and friendships 
						to family relationships and self-image. Understanding that others go through similar 
						experiences can help you feel less alone.
					</p>
				</div>

				<div className="about-subsection teen-stories">
					<h3>Real Stories of Hope</h3>
					<p className="subsection-intro">
						Watch how other teenagers found their way through mental health challenges. 
						Their stories show that recovery is possible and help is available.
					</p>
					
					<div className="video-grid">
						<div className="video-container">
							<iframe
								width="100%"
								height="400"
								src="https://www.youtube.com/embed/G9nhT46Zv40"
								title="Teen Mental Health Stories"
								frameBorder="0"
								allow="accelerometer; autoplay; clipboard-write; encrypted-media; gyroscope; picture-in-picture"
								allowFullScreen
							></iframe>
						</div>
						
						<div className="video-container">
							<iframe
								width="100%"
								height="400"
								src="https://www.youtube.com/embed/LFw8N-pNOn4"
								title="Mental Health Journey Stories"
								frameBorder="0"
								allow="accelerometer; autoplay; clipboard-write; encrypted-media; gyroscope; picture-in-picture"
								allowFullScreen
							></iframe>
						</div>
					</div>
				</div>
			</div>
		</section>
	);
};

export default AboutSection;